class Component extends DCLogic {
  constructor(props) { super(props); this.state = { card: '', compose: false, cText: '', cErr: false, note: '', hl: '', toast: '', view: '' }; }
  componentDidMount() { this._esc = (e) => { if (e.key === 'Escape') this.setState({ card: '' }); }; document.addEventListener('keydown', this._esc); }
  componentWillUnmount() { document.removeEventListener('keydown', this._esc); clearTimeout(this._tt); }
  say(msg) { this.setState({ toast: msg }); clearTimeout(this._tt); this._tt = setTimeout(() => this.setState({ toast: '' }), 3800); }
  common() {
    const S = this.state;
    const BD = { ok: 'badge--ok', warn: 'badge--warn', wait: 'badge--muted' }, DT = { ok: 'dt--ok', warn: 'dt--warn', wait: 'dt--muted' };
    /* люди из текущей карты: [id, ФИО, коротко, кто пригласил, уровень, состояние, подпись состояния] */
    const raw = HB.net.raw();
    const by = {};
    raw.forEach((r) => { by[r[0]] = { id: r[0], name: r[1], short: r[2], par: r[3], lvl: r[4], st: r[5], tag: r[6], badge: BD[r[5]], dot: DT[r[5]], l1: r[4] === 1, ini: r[1].split(' ').map((w) => w[0]).join('') }; });
    const N = raw.map((r) => by[r[0]]);
    N.forEach((n) => { n.br = n.par ? by[n.par].br : n.id; n.byS = n.par ? by[n.par].short : 'Вы'; n.bcls = 'b-' + n.br; n.nol1 = !n.l1; n.open = n.l1 ? () => this.setState({ card: n.id, compose: false, cText: '', cErr: false, note: '' }) : () => {}; n.aria = (n.l1 ? 'Партнёр первого уровня: ' + n.name + ', ' + n.tag + '. Открыть карточку, чтобы написать' : n.lvl + '-й уровень: ' + n.name + ', ' + n.tag + '. Пригласил: ' + n.byS); });
    const kids = (id) => N.filter((x) => x.par === id);
    const descN = (id) => kids(id).reduce((a, x) => a + 1 + descN(x.id), 0);
    const L1 = N.filter((n) => n.l1);
    const lvN = [0, 0, 0, 0, 0, 0]; N.forEach((n) => { lvN[n.lvl]++; });
    const sumRows = [1, 2, 3, 4, 5].map((k) => ({ n: lvN[k], t: k + '-й уровень' })).concat([{ n: N.length, t: 'Всего в сети' }]);
    const ru = (n, a, b, c) => { const m = n % 100, d = n % 10; return (m > 10 && m < 15) ? c : d === 1 ? a : (d > 1 && d < 5) ? b : c; };

    /* карточка партнёра первого уровня */
    const F = HB.net.F;
    const cid = S.card; let card = {}, cardOpen = false;
    if (cid && by[cid]) {
      cardOpen = true;
      const x = by[cid], f = F[cid], nk = descN(cid), cE = S.cErr && !S.cText.trim();
      const branch = [];
      const walk = (id) => kids(id).forEach((k) => { branch.push({ name: k.name, lvl: k.lvl + '-й уровень', badge: k.badge, tag: k.tag }); walk(k.id); });
      walk(cid);
      card = {
        name: x.name, badge: x.badge, tag: x.tag, tone: x.st === 'warn' ? 'err' : 'ok', warn: x.st === 'warn', good: x.st !== 'warn', hint: f[2],
        since: f[3], lastIn: f[4], mail: f[0], phone: f[1], note: S.note, kids: String(nk), hasKids: nk > 0, br: branch,
        close: () => this.setState({ card: '' }),
        copy: () => this.setState({ note: 'Телефон скопирован' }),
        tel: 'tel:+' + f[1].replace(/\D/g, ''), sent: S.note.indexOf('Сообщение отправлено') === 0, openChat: () => { HB.net.openChat(cid); window.location.href = 'soobshcheniya-chat.html'; },
        write: () => this.setState({ compose: !S.compose, note: '' }),
        compose: S.compose, chips: ['Чем помочь с первым клиентом?', 'Чего не хватает для работы?', 'Как дела с клиентами?'].map((t) => ({ t, pick: () => this.setState({ cText: t, cErr: false }) })),
        cText: S.cText, cSet: (e) => this.setState({ cText: e.target.value, cErr: false }), cErr: cE ? 'is-err' : '', cErr_e: cE ? 'Напишите сообщение или выберите фразу' : '',
        cSend: (e) => { if (e && e.preventDefault) e.preventDefault(); if (!S.cText.trim()) { this.setState({ cErr: true }); return; } HB.net.send(cid, S.cText.trim()); this.setState({ compose: false, cText: '', note: 'Сообщение отправлено: ' + x.name + '. Оно в «Сообщениях».' }); },
        cCancel: () => this.setState({ compose: false, cText: '', cErr: false })
      };
    }
    const tabs = [['over', 'Обзор'], ['map', 'Карта сети'], ['cl', 'Клиенты сети']].map(([k, t]) => ({ t, sel: k === 'map' ? 'true' : 'false', pick: () => { if (k !== 'map') window.location.href = 'moya-set.html?tab=' + k; } }));
    const vals = { cardOpen, card, tabs, sumRows, toastOn: !!S.toast, toast: S.toast,
      invOpen: () => { window.location.href = 'moya-set.html?invite=1'; } };
    return { S, N, by, kids, descN, L1, lvN, ru, vals };
  }
  renderVals() { const c = this.common(); return Object.assign(c.vals, this.extra(c)); }


  mapVals(c, view) {
    const { N, L1, descN, kids } = c;
    const MOB = !!c.mob;
    const R = [0.2, 0.275, 0.34, 0.395, 0.445];                       /* радиусы колец, доля ширины схемы */
    const MAXS = MOB ? [4.6, 4.2, 3.6, 3.1, 2.8] : [3.8, 3.3, 2.9, 2.6, 2.4];   /* наибольший диаметр точки, cqw */
    const MINS = MOB ? 2.5 : 1.9, GAPC = MOB ? 0.4 : 0.4, FILL = 0.8, TOPG = 14, GAPD = 1.2;
    const f = (v) => v.toFixed(2);
    const sorted = L1.slice().sort((a, b) => descN(b.id) - descN(a.id));
    const kc = {}; sorted.forEach((b, i) => { kc[b.id] = i < 5 ? 'k' + (i + 1) : 'kg'; });
    const cls = (n) => kc[n.br] + ' ' + n.bcls;
    /* сектора: ширина пропорциональна числу людей; у каждого партнёра не меньше угла под свою точку первого уровня */
    const circ = (k) => 2 * Math.PI * R[k - 1] * 100;
    const s1 = Math.min(MAXS[0], FILL * circ(1) / L1.length);
    const minA = (s1 + GAPC) / (R[0] * 100) * 180 / Math.PI + GAPD;
    const wt = sorted.map((b) => descN(b.id) + 1), avail = 360 - TOPG;
    const span = wt.map(() => 0), fixed = wt.map(() => false);
    for (let it = 0; it < 20; it++) {
      const free = wt.reduce((a, w, i) => a + (fixed[i] ? 0 : w), 0), left = avail - span.reduce((a, s, i) => a + (fixed[i] ? s : 0), 0);
      let ch = false; wt.forEach((w, i) => { if (!fixed[i]) { span[i] = left * w / free; if (span[i] < minA) { span[i] = minA; fixed[i] = true; ch = true; } } });
      if (!ch) break;
    }
    const ang = {}, wedges = [];
    let a0 = -90 + TOPG / 2;
    sorted.forEach((b, i) => {
      const nl0 = (id) => { const ks = kids(id); return ks.length ? ks.reduce((a, x) => a + nl0(x.id), 0) : 1; };
      const nl = nl0(b.id); let li = 0;
      const place = (n) => { const ks = kids(n.id); if (!ks.length) { ang[n.id] = a0 + (li++ + 0.5) * span[i] / nl; return; } ks.forEach(place); ang[n.id] = (ang[ks[0].id] + ang[ks[ks.length - 1].id]) / 2; };
      place(b); ang[b.id] = a0 + span[i] / 2; /* точка партнёра по центру его сектора */
      if (descN(b.id) > 0) wedges.push({ bcls: cls(b), sty: 'background:conic-gradient(from ' + f(a0 + 90 + GAPD / 2) + 'deg,color-mix(in srgb,var(--bc) ' + (kc[b.id] === 'kg' ? (i % 2 ? 8 : 16) : 14) + '%,var(--hb-paper)) 0 ' + f(span[i] - GAPD) + 'deg,transparent ' + f(span[i] - GAPD) + 'deg);width:100%;height:100%;-webkit-mask-image:radial-gradient(farthest-side,#000 ' + f((R[4] + 0.03) * 200) + '%,transparent ' + f((R[4] + 0.03) * 200) + '%);mask-image:radial-gradient(farthest-side,#000 ' + f((R[4] + 0.03) * 200) + '%,transparent ' + f((R[4] + 0.03) * 200) + '%)' });
      a0 += span[i];
    });
    /* кольца: размер точки по числу людей на кольце, раздвигание соседей, плотная полоса, если не помещается */
    const size = {}, dense = [], pos = {}, sizeK = [];
    const stats = [];
    for (let k = 1; k <= 5; k++) {
      const mem = N.filter((n) => n.lvl === k).sort((a, b) => ang[a.id] - ang[b.id]);
      const r100 = R[k - 1] * 100, n = mem.length;
      if (n * (MINS + GAPC) > FILL * circ(k)) { dense[k] = true; sizeK[k] = 0; stats.push({ k, n, dense: true }); mem.forEach((m) => { pos[m.id] = { a: ang[m.id], r: R[k - 1] }; }); continue; }
      let s = Math.min(MAXS[k - 1], FILL * circ(k) / n), A = mem.map((m) => ang[m.id]), tgt = A.slice(), ok = false;
      for (; s >= MINS - 1e-9 && !ok; s -= 0.1) {
        const gap = (s + GAPC) / r100 * 180 / Math.PI; A = tgt.slice();
        for (let it = 0; it < 400; it++) {
          let mv = false;
          for (let i = 0; i < n; i++) { const j = (i + 1) % n; let d = A[j] - A[i]; if (j === 0) d += 360; if (d < gap - 1e-3) { const e = (gap - d) / 2; A[i] -= e; A[j] += e; mv = true; } }
          if (!mv) break;
        }
        ok = true; for (let i = 0; i < n; i++) { const j = (i + 1) % n; let d = A[j] - A[i]; if (j === 0) d += 360; if (d < gap - 0.05) ok = false; }
      }
      s += 0.1;
      if (!ok) { dense[k] = true; sizeK[k] = 0; stats.push({ k, n, dense: true }); mem.forEach((m) => { pos[m.id] = { a: ang[m.id], r: R[k - 1] }; }); continue; }
      sizeK[k] = s; let md = 0; mem.forEach((m, i) => { pos[m.id] = { a: A[i], r: R[k - 1] }; md = Math.max(md, Math.abs(A[i] - tgt[i])); });
      stats.push({ k, n, s: +s.toFixed(2), maxShift: +md.toFixed(1) });
    }
    this._stats = stats; if (typeof window !== 'undefined') window.__ringStats = stats;
    N.forEach((n) => { const p = pos[n.id], a = p.a * Math.PI / 180; p.x = 50 + p.r * 100 * Math.cos(a); p.y = 50 + p.r * 100 * Math.sin(a); });
    const rings = [1, 2, 3, 4, 5].map((k) => ({ sty: 'left:50%;top:50%;width:' + f(R[k - 1] * 200) + '%;height:' + f(R[k - 1] * 200) + '%' }));
    const rls = [1, 2, 3, 4, 5].map((k) => ({ t: String(k), sty: 'left:50%;top:' + f(50 - R[k - 1] * 100) + '%' }));
    const spokes = [];
    N.forEach((n) => { if (dense[n.lvl] || (n.par && dense[n.lvl - 1])) return; const p = n.par ? pos[n.par] : { x: 50, y: 50 }, q = pos[n.id]; const dx = q.x - p.x, dy = q.y - p.y; spokes.push({ cls: cls(n), sty: 'left:' + f(p.x) + '%;top:' + f(p.y) + '%;width:' + f(Math.hypot(dx, dy)) + 'cqw;transform:rotate(' + f(Math.atan2(dy, dx) * 180 / Math.PI) + 'deg)' }); });
    const tp = (p) => (p.x > 66 ? 'tl' : p.x < 34 ? 'tr' : '');
    const dots = N.filter((n) => !dense[n.lvl]).sort((a, b) => b.lvl - a.lvl).map((n) => { const p = pos[n.id], s = sizeK[n.lvl];
      return { l1: n.l1, nol1: n.nol1, bcls: cls(n), ini: (!MOB && s >= 3.2) ? n.ini : '', name: n.name, sub: n.lvl === 1 ? '1-й уровень, ' + n.tag + '. В ветке ' + (descN(n.id) + 1) : n.lvl + '-й уровень, ' + n.tag + '. Пригласил: ' + n.byS, open: n.open, aria: n.aria, tp: tp(p),
        sty: 'left:' + f(p.x) + '%;top:' + f(p.y) + '%;width:' + f(s) + 'cqw;height:' + f(s) + 'cqw;font-size:' + f(s * 0.36) + 'cqw' }; });
    /* плотные кольца: дуги по веткам с числом людей */
    const arcs = [], arcn = [];
    [1, 2, 3, 4, 5].filter((k) => dense[k]).forEach((k) => {
      const bw = 3.4, ri = (R[k - 1] - bw / 200) * 200, ro = (R[k - 1] + bw / 200) * 200;
      sorted.forEach((b) => { const m = N.filter((n) => n.lvl === k && n.br === b.id); if (!m.length) return;
        const as = m.map((x) => pos[x.id].a), lo = Math.min(...as) - 0.9, hi = Math.max(...as) + 0.9, mid = (lo + hi) / 2, p = { x: 50 + R[k - 1] * 100 * Math.cos(mid * Math.PI / 180), y: 50 + R[k - 1] * 100 * Math.sin(mid * Math.PI / 180) };
        arcs.push({ bcls: cls(b), sty: '--ri:' + f(ri) + '%;--ro:' + f(ro) + '%;background:conic-gradient(from ' + f(lo + 90) + 'deg,var(--bc) 0 ' + f(hi - lo) + 'deg,transparent ' + f(hi - lo) + 'deg)' });
        if ((hi - lo) / 180 * Math.PI * R[k - 1] * 100 >= 3.2 || m.length > 1) arcn.push({ bcls: cls(b), t: String(m.length), aria: 'Ветка ' + b.short + ': ' + m.length + ' ' + c.ru(m.length, 'человек', 'человека', 'человек') + ' на ' + k + '-м кольце', name: 'Ветка ' + b.short, sub: m.length + ' ' + c.ru(m.length, 'человек', 'человека', 'человек') + ' на ' + k + '-м кольце', tp: tp(p), sty: 'left:' + f(p.x) + '%;top:' + f(p.y) + '%' });
      });
    });
    const dk = [1, 2, 3, 4, 5].filter((k) => dense[k]);
    const denseTxt = dk.length ? 'Кольцо ' + dk.join(', ') + ' плотное: людей больше, чем помещается точками. Оно нарисовано дугами по веткам, цифра это число людей, имена в карточке партнёра.' : '';
    const legend = sorted.map((b) => { const n = descN(b.id) + 1; return { bcls: cls(b), ini: b.ini, name: b.name, open: b.open, aria: b.aria, cnt: n + ' ' + (n === 1 ? 'человек, один' : 'чел.') }; });
    legend.forEach((l, i) => { const n = descN(sorted[i].id) + 1; l.cnt = n === 1 ? '1 человек' : n + ' чел.'; });
    /* список ветками: тот же порядок и цвета, что на кольцах */
    const DOT = { ok: 'dt--ok', warn: 'dt--warn', wait: 'dt--muted' };
    const br = sorted.map((b) => {
      const rows = []; let maxL = 1;
      const walk = (id, anc) => { const ks = kids(id); ks.forEach((k, j) => { const last = j === ks.length - 1; const g = anc.map((v) => (v ? 'v' : '')).concat([last ? 'l' : 'e']); maxL = Math.max(maxL, k.lvl);
        rows.push({ g, sty: '--d:' + g.length, lvl: k.lvl, name: k.name, short: k.short, dot: k.dot || DOT[k.st], aria: k.aria, tip: k.name + ', ' + k.tag + '. Пригласил: ' + k.byS }); walk(k.id, anc.concat([!last])); }); };
      walk(b.id, []);
      return { cls: cls(b), sty: '--w:' + Math.max(156, 12 * (maxL - 1) + 132) + 'px', name: b.name, badge: b.badge, tag: b.tag, open: b.open, aria: b.aria, rows };
    });
    return { wedges, rings, arcs, spokes, rls, arcn, dots, legend, hasDense: dk.length > 0, denseTxt, br,
      vRings: view === 'rings', vList: view === 'list', setRings: () => { HB.store.set('ui.mapView', 'rings'); this.setState({ view: 'rings' }); }, setList: () => { HB.store.set('ui.mapView', 'list'); this.setState({ view: 'list' }); } };
  }
  extra(c) { return this.mapVals(Object.assign({ mob: false }, c), c.S.view || (false ? 'list' : 'rings')); }
}

Component = (function (Base) { return class extends Base {
  constructor(props) { super(props); const mv = HB.store.get('ui.mapView'); if (mv === 'rings' || mv === 'list') this.state.view = mv; }
  renderVals() { const v = super.renderVals(); const S = this.state, set = (o) => this.setState(o);  return v; }
}; })(Component);
